SELECT relname AS table_name, obj_description(relfilenode, 'pg_class') AS description

ORDER BY table_name
LIMIT #{limit} OFFSET #{offset}

SELECT EXISTS(
               SELECT 1
               FROM information_schema.columns
               WHERE table_name = #{tableName}
                 AND column_name = #{columnName}
                 AND table_schema = #{schemaName}
           )

SELECT EXISTS(
               SELECT 1
               FROM information_schema.tables
               WHERE table_schema = #{schemaName}
                 AND table_name = #{tableName}
           )

mapper.insert:

CREATE TABLE IF NOT EXISTS "${schemaName}"."${table.tableName}" (
id SERIAL PRIMARY KEY,


         "${col.columnName}" ${col.type}


);

COMMENT ON TABLE "${schemaName}"."${table.tableName}" IS '${table.description}';


        COMMENT ON COLUMN "${schemaName}"."${table.tableName}"."${col.columnName}" IS '${col.description}'

update.foreach:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = '${tableName}' AND column_name = '${col.columnName}' AND table_schema = '${schemaName}') THEN
        EXECUTE 'ALTER TABLE "${schemaName}"."${tableName}" ALTER COLUMN "${col.columnName}" TYPE ${col.type} USING "${col.columnName}"::${col.type}';
    ELSE
        EXECUTE 'ALTER TABLE "${schemaName}"."${tableName}" ADD COLUMN "${col.columnName}" ${col.type}';
    END IF;
END $$;

mapper.update:
CREATE SCHEMA IF NOT EXISTS "${schemaName}";

CREATE TABLE IF NOT EXISTS "${schemaName}"."table_field_mapping" (
    id SERIAL PRIMARY KEY,
    source_table_name  varchar(255)                                                         not null,
    source_column_name varchar(255)                                                         not null,
    target_table_name  varchar(255)                                                         not null,
    target_column_name varchar(255)                                                         not null,
    create_time        timestamp(6) default CURRENT_TIMESTAMP,
    constraint table_field_mapping_uk_source_target_table
        unique (source_table_name, target_table_name)
);

COMMENT ON TABLE "${schemaName}"."table_field_mapping" IS '主属性表和关联属性表主外建映射';
COMMENT ON COLUMN "${schemaName}"."table_field_mapping".source_table_name IS '主属性表名';
COMMENT ON COLUMN "${schemaName}"."table_field_mapping".source_column_name IS '主属性表被关联列';
COMMENT ON COLUMN "${schemaName}"."table_field_mapping".target_table_name IS '关联属性表名';
COMMENT ON COLUMN "${schemaName}"."table_field_mapping".target_column_name IS '关联属性表关联列名';
COMMENT ON COLUMN "${schemaName}"."table_field_mapping".create_time IS '创建时间';
